            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            padding: 0;
            background-color: #e9ecef;
            color: var(--dark);
        }
        header {
            background-color: var(--primary);
            color: white;
            text-align: center;
            padding: 2rem;
        }
        header h1 {
            margin: 0;
            font-size: 2.5rem;
        }
        nav {
            background-color: #1a252f;
            color: white;
            padding: 0.5rem;
            text-align: center;
        }
        nav a {
            color: white;
            text-decoration: none;
            margin: 0 15px;
            font-weight: bold;
        }
        nav a:hover {
            color: var(--secondary);
        }
        .container {
            max-width: 900px;
            margin: 20px auto;
            background: white;
            padding: 30px;
            border-radius: 8px;
            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
        }
        section {
            margin-bottom: 30px;
        }
        h2 {
            color: var(--primary);
            border-bottom: 2px solid var(--secondary);
            padding-bottom: 5px;
        }
        .btn {
            display: inline-block;
            background-color: var(--secondary);
            color: var(--dark);
            padding: 10px 20px;
            text-decoration: none;
            font-weight: bold;
            border-radius: 5px;
            margin-top: 10px;
        }
        .btn:hover {
            background-color: #b7950b;
            color: white;
        }
        footer {
            text-align: center;
            padding: 1rem;
            background-color: var(--primary);
            color: white;
            margin-top: 30px;
        }
    </style>
</head>
<body>

    <header>
      ♔ ♕ ♖ ♗ ♘ ♙
        <h1>Knight Riders Chess Club</h1>
        <p>All levels welcome — from absolute beginners to Grandmasters!</p>
    </header>

    <nav>
        <a href="#about">About Us</a>
        <a href="#meetings">Meetings</a>
        <a href="#events">Tournaments</a>
        <a href="#contact">Contact</a>
    </nav>

    <div class="container">

        <section id="about">
            <h2>About Our Club</h2>
            <p>Welcome to the Knight Riders Chess Club! We meet weekly to play casual games, analyze famous matches, learn tactical openings, and host friendly internal tournaments. Whether you don't know how the knight moves or you're rated 2000+, you have a place here.</p>
        </section>

        <section id="meetings">
            <h2>When & Where We Meet</h2>
            <ul>
                <li><strong>Days:</strong> Every Tuesday and Thursday</li>
                <li><strong>Time:</strong> 6:00 PM – 8:30 PM</li>
                <li><strong>Location:</strong> Room 304, Community Center (or Downtown Library)</li>
                <li><strong>Cost:</strong> Completely Free! (Boards and clocks provided)</li>
            </ul>
        </section>

        <section id="events">
            <h2>Upcoming Events</h2>
            <p><strong>Spring Rapid Tournament:</strong> Saturday, May 15th at 10:00 AM. Time control: 15+10. Prizes for 1st, 2nd, and Best Under-1200!</p>
            <a href="#contact" class="btn">Register for Tournament</a>
        </section>

        <section id="contact">
            <h2>Get In Touch</h2>
            <p>Have questions? Want to join our mailing list or Discord server?</p>
            <p><strong>Email:</strong> info@knightriderschess.com</p>
            <p><strong>Discord:</strong> <a href="#" target="_blank">Join our server</a></p>
        </section>

    </div>

    <footer>
        <p>&copy; 2023 Knight Riders Chess Club. Checkmate!</p>
    </footer>

</body>
</html>
